args.command:
/bin/bash -c "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
const cases = [
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/lamp', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp'],
]
for (const [path, name, price, related] of cases) {
  const response = await fetch("'`http://127.0.0.1:3111${path}`)
  assert.equal(response.status, 200, path)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let html = '"''
  const chunks = []
  for (;;) {
    const { done, value } = await reader.read()
    if (done) break
    const chunk = decoder.decode(value, { stream: true })
    chunks.push(chunk)
    html += chunk
  }
  assert.match(html, /Signal Shop collection/)
  assert.ok(html.includes(name), "'`${path}: name missing`)
  assert.ok(html.includes(price), `${path}: price missing`)
  assert.ok(html.includes(related), `${path}: related missing`)
  console.log(`${path}: ${name}, ${price}, related ${related}; ${chunks.length} chunks`)
  if (path.includes('"'lamp?')) {
    assert.ok(chunks[0].includes('Loading product details...'), 'shell fallback missing')
    assert.ok(chunks.slice(1).join('').includes('Loading related products...'), 'related fallback missing')
  }
}
NODE
printf '\\n--- generated changes ---\\n'; git diff -- next-env.d.ts tsconfig.json; cat .gitignore"

